#' Adverse Events Butterfly Plot
#'
#' Back-to-back (butterfly) bar plot of adverse-event frequencies by preferred
#' term, comparing a test arm against an optional control arm and splitting 
#' each
#' bar into all-grade and high-grade (e.g. grade >= 3) severity.
#' Accepts patient-level data (incidence computed internally) or 
#' pre-summarized
#' percentages. Inspired by the Jamovi-TrialPlots module by highwind.
#' 
#' @param data .
#' @param inputMode 'patient' computes adverse-event incidence from
#'   patient-level rows; 'summary' reads pre-computed all-grade and high-grade
#'   percentages.
#' @param subjectID Subject identifier used as the incidence denominator
#'   (distinct subjects).
#' @param aeTerm Adverse-event preferred term (one row per subject-event).
#' @param armVar Optional treatment arm. When omitted the plot shows a single
#'   arm.
#' @param gradeVar Optional numeric severity grade used to derive the
#'   high-grade split.
#' @param gradeThreshold Events with grade greater than or equal to this value
#'   count as high grade.
#' @param aeTermS Adverse-event term column for pre-summarized input.
#' @param testAll Test-arm all-grade incidence percentage.
#' @param testHigh Test-arm high-grade incidence percentage.
#' @param controlAll Control-arm all-grade incidence percentage (optional).
#' @param controlHigh Control-arm high-grade incidence percentage (optional).
#' @param barShape 'inside' overlays high-grade on all-grade; 'outside' stacks
#'   the two.
#' @param colorScheme Journal-style color palette (via ggsci) for the test
#'   arm.
#' @param showValues Print the all-grade percentage next to each bar.
#' @param topN Keep only the N most frequent terms (by test-arm all-grade); 0
#'   shows all.
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$instructions} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$freqTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$interpretation} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$freqTable$asDF}
#'
#' \code{as.data.frame(results$freqTable)}
#'
#' @export
aeplot <- function(
    data,
    inputMode = "patient",
    subjectID = NULL,
    aeTerm = NULL,
    armVar = NULL,
    gradeVar = NULL,
    gradeThreshold = 3,
    aeTermS = NULL,
    testAll = NULL,
    testHigh = NULL,
    controlAll = NULL,
    controlHigh = NULL,
    barShape = "inside",
    colorScheme = "nejm",
    showValues = FALSE,
    topN = 0) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("aeplot requires jmvcore to be installed (restart may be required)")

    if ( ! missing(subjectID)) subjectID <- jmvcore::resolveQuo(jmvcore::enquo(subjectID))
    if ( ! missing(aeTerm)) aeTerm <- jmvcore::resolveQuo(jmvcore::enquo(aeTerm))
    if ( ! missing(armVar)) armVar <- jmvcore::resolveQuo(jmvcore::enquo(armVar))
    if ( ! missing(gradeVar)) gradeVar <- jmvcore::resolveQuo(jmvcore::enquo(gradeVar))
    if ( ! missing(aeTermS)) aeTermS <- jmvcore::resolveQuo(jmvcore::enquo(aeTermS))
    if ( ! missing(testAll)) testAll <- jmvcore::resolveQuo(jmvcore::enquo(testAll))
    if ( ! missing(testHigh)) testHigh <- jmvcore::resolveQuo(jmvcore::enquo(testHigh))
    if ( ! missing(controlAll)) controlAll <- jmvcore::resolveQuo(jmvcore::enquo(controlAll))
    if ( ! missing(controlHigh)) controlHigh <- jmvcore::resolveQuo(jmvcore::enquo(controlHigh))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(subjectID), subjectID, NULL),
            `if`( ! missing(aeTerm), aeTerm, NULL),
            `if`( ! missing(armVar), armVar, NULL),
            `if`( ! missing(gradeVar), gradeVar, NULL),
            `if`( ! missing(aeTermS), aeTermS, NULL),
            `if`( ! missing(testAll), testAll, NULL),
            `if`( ! missing(testHigh), testHigh, NULL),
            `if`( ! missing(controlAll), controlAll, NULL),
            `if`( ! missing(controlHigh), controlHigh, NULL))

    for (v in aeTerm) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])
    for (v in armVar) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])
    for (v in aeTermS) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- aeplotOptions$new(
        inputMode = inputMode,
        subjectID = subjectID,
        aeTerm = aeTerm,
        armVar = armVar,
        gradeVar = gradeVar,
        gradeThreshold = gradeThreshold,
        aeTermS = aeTermS,
        testAll = testAll,
        testHigh = testHigh,
        controlAll = controlAll,
        controlHigh = controlHigh,
        barShape = barShape,
        colorScheme = colorScheme,
        showValues = showValues,
        topN = topN)

    analysis <- aeplotClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

